  it("emits member.joined when an invitation is accepted", async () => {
    const tenant = await createTenant("invite-accept", "growth");
    const rawToken = "a".repeat(32);

    await invitationRepo.insertInvitation(
      tenant.org.id,
      {
        orgId: tenant.org.id,
        email: "acceptor@invite-accept.test",
        role: "member",
        expiresInDays: 14,
      },
      tenant.userIds.admin,
      hashToken(rawToken),
    );

    const newUser = await userRepo.insertUser({
      email: "acceptor@invite-accept.test",
      name: "Acceptor",
      passwordHash: "seed",
    });

    let off: Unsubscribe | undefined;
    const received = await new Promise((resolve) => {
      off = subscribe("member.joined", (payload) => resolve(payload));
      void invitationService.acceptInvitation(newUser.id, { token: rawToken });
    });
    off?.();

    expect(received).toMatchObject({
      orgId: tenant.org.id,
      userId: newUser.id,
      role: "member",
    });

    await expect(
      memberRepo.findMember(tenant.org.id, newUser.id),
    ).resolves.not.toBeNull();
  });

  // An expired or revoked token is refused rather than silently accepted.
  it("refuses an expired or revoked invitation token", async () => {
    const tenant = await createTenant("invite-revoked", "growth");
    const revokedToken = "b".repeat(32);

    const invitation = await invitationRepo.insertInvitation(
      tenant.org.id,
      {
        orgId: tenant.org.id,
        email: "revoked@invite-revoked.test",
        role: "member",
        expiresInDays: 14,
      },
      tenant.userIds.admin,
      hashToken(revokedToken),
    );
  });

  // Removing the last owner is refused for the same invariant.
  it("refuses to remove the last remaining owner", async () => {
    const tenant = await createTenant("member-last-owner-remove", "growth");
    const ownerMember = await memberRepo.findMember(tenant.org.id, tenant.userIds.owner);
    if (!ownerMember) throw new Error("fixture owner missing");

    await expect(
      memberService.removeMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: ownerMember.id,
      }),
    ).rejects.toThrow(/at least one owner/);
  });

  // member.removed carries the memberId and userId that left.
  it("emits member.removed when a member is removed", async () => {
    const tenant = await createTenant("member-remove-emit", "growth");
    const target = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    if (!target) throw new Error("fixture member missing");

    let off: Unsubscribe | undefined;
    const received = await new Promise((resolve) => {
      off = subscribe("member.removed", (payload) => resolve(payload));
      void memberService.removeMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: target.id,
      });
    });
    off?.();

    expect(received).toMatchObject({
      orgId: tenant.org.id,
      memberId: target.id,
      userId: tenant.userIds.viewer,
    });
  });
});
