export async function resolveActor(
  userId: UserId,
  orgId: OrgId,
): Promise<Actor | null> {
  const member = await memberRepo.findMember(orgId, userId);
  if (!member || !memberRepo.isCurrentMember(member)) return null;

  return { userId, orgId, role: member.role };
}

/**
 * Refuses the write when any of `userIds` is not a current member of the org.
 * Assignees and project leads are checked here before anything is written, so
 * a refused change leaves nothing behind. `null` and `undefined` mean "no one"
 * and are skipped.
 */
export async function assertCurrentMembers(
  orgId: OrgId,
  userIds: readonly (UserId | null | undefined)[],
): Promise<void> {
  const wanted = [...new Set(userIds.filter((id): id is UserId => id != null))];
  if (wanted.length === 0) return;

  const current = await memberRepo.filterCurrentMembers(orgId, wanted);
  if (wanted.some((id) => !current.has(id))) {
    throw new Error("Only current members of this organization can be assigned or made lead");
  }
}

